/** Overlay translated fields onto a Crucible for the given locale.
 *  Falls back to English for any missing field or locale. */
export function localizeCrucible(c: Crucible, locale: Locale): Crucible {
  if (locale === 'en') return c;
  const o = CRUCIBLE_I18N[String(c.id)]?.[locale];
  if (!o) return c;
  const prompt = o.prompt ?? c.prompt;
  const framing = o.framing ?? c.framing;
  if (prompt === c.prompt && framing === c.framing) return c;
  return { ...c, prompt, framing };
}
